variants.code_sketch:
function createServer({ host = 'localhost', port = 8080, tls = false } = {}) {
  return { host, port, tls };
}

createServer({ port: 9000 });   // host and tls keep their defaults
createServer();                // works because of the outer `= {}`

const defaults = Object.freeze({ host: 'localhost', port: 8080, tls: false });

function createServer(overrides = {}) {
  const cfg = { ...defaults, ...overrides };
  // shallow copy: nested objects stay shared with `overrides`
  return cfg;
}

createServer({ port: 9000, tls: undefined });  // tls is now undefined, not false
